import{_ as e}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as r,o as a,c as d,a2 as o}from"./chunks/framework.CqGPl1zp.js";const p="/newx-doc/assets/%E5%8A%9F%E8%83%BD%E5%88%97%E8%A1%A8.mfvGVU2u.png",l="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.CA2QKuvE.png",s="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.ftmAzDtk.png",i="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.CX3om9LU.png",c="/newx-doc/assets/%E7%AC%AC%E4%B8%89%E6%AD%A5-01.CY3PkD0Y.png",E=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"mp/build.md","filePath":"mp/build.md","lastUpdated":null}'),m={name:"mp/build.md"};function n(u,t,_,h,b,f){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p><a href="https://developers.weixin.qq.com/doc/offiaccount/Getting_Started/Overview.html" target="_blank" rel="noreferrer">微信公众号</a> 的功能，由 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/" target="_blank" rel="noreferrer"><code>yudao-module-mp</code></a> 模块实现，对应前端代码为 <a href="https://github.com/yudaocode/yudao-ui-admin-vue3/tree/master/src/views/mp" target="_blank" rel="noreferrer"><code>@/views/mp</code></a> 目录。</p><p>主要包括如下 10 个功能（菜单）：</p><p><img src="'+p+'" alt="功能列表"></p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th></tr></thead><tbody><tr><td>账号管理</td><td>配置接入的微信公众号，可支持多个公众号</td></tr><tr><td>数据统计</td><td>统计公众号的用户增减、累计用户、消息概况、接口分析等数据</td></tr><tr><td>粉丝管理</td><td>查看已关注、取关的粉丝列表，可对粉丝进行同步、打标签等操作</td></tr><tr><td>消息管理</td><td>查看粉丝发送的消息列表，可主动回复粉丝消息</td></tr><tr><td>模版消息</td><td>配置和发送模版消息，用于向粉丝推送通知类消息</td></tr><tr><td>自动回复</td><td>自动回复粉丝发送的消息，支持关注回复、消息回复、关键字回复</td></tr><tr><td>标签管理</td><td>对公众号的标签进行创建、查询、修改、删除等操作</td></tr><tr><td>菜单管理</td><td>自定义公众号的菜单，也可以从公众号同步菜单</td></tr><tr><td>素材管理</td><td>管理公众号的图片、语音、视频等素材，支持在线播放语音、视频</td></tr><tr><td>图文草稿箱</td><td>新增常用的图文素材到草稿箱，可发布到公众号</td></tr><tr><td>图文发表记录</td><td>查看已发布成功的图文素材，支持删除操作</td></tr></tbody></table><p>考虑到编译速度，默认 <code>yudao-module-mp</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-mp</code> 模块</li><li>第二步，导入公众号的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-mp</code> 模块的注释。如下图所示：</p><p><img src="'+l+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-mp</code> 模块。如下图所示：</p><p><img src="'+s+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+e+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/mp.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ mp.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+i+'" alt="导入数据库"></p><p>以 <code>mp_</code> 作为前缀的表，就是公众号模块的表。</p><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的公众号菜单，确认功能是否生效。如下图所示：</p><p><img src="'+c+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了公众号的功能 🙂</p>',24)])])}const x=r(m,[["render",n]]);export{E as __pageData,x as default};
